#include <torch/library.h>
#include <torch/csrc/autograd/custom_function.h>
#include "pytorch_npu_helper.hpp"
#include <torch/extension.h>

at::Tensor instance_norm_custom_impl_npu(const at::Tensor& x, const at::Tensor& gamma, const at::Tensor& beta) {
    at::Tensor y = at::empty_like(x);
    EXEC_NPU_CMD(aclnnInstanceNormCustom, x, gamma, beta, y);
    return y;
}

TORCH_LIBRARY_IMPL(myops, PrivateUse1, m) {
    m.impl("instance_norm_custom", &instance_norm_custom_impl_npu);
}

